window.products.push({"id":328903,"name":"Organize It All 2 Pack Zippered Blanket Storage Bag in Clear","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/719PCyMvpcL._AC_SL1500_.jpg","description":"Organize It All’s 2 Pack Blanket Bag is made of nonwoven breathable material that keeps your blankets and other belongings safe. It is the perfect storage solution for off-season items such as blankets, comforters, garments, and more. It also protects them against dust and damage thanks to its full zippered top. The see-through PVC zippered lid allows you to look inside of the bag to find exactly what you need. The flexible design makes it easy to fit in tight spaces to store. You can keep it tucked away in your closet or it slides nicely under your bed.","images":["https://m.media-amazon.com/images/I/719PCyMvpcL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Organize It All","source_asin":"B001L72CNO","category_path":"Home & Kitchen"},"sku":"BM-328903","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B001L72CNO","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B001L72CNO","price_pending":true,"merchant_ready":false});
